rows=[]
for col, school, major, certs in MAJ:
    for name, pri, why in certs:
        kind, org, link = CERT[name]
        rows.append({"단과대학":col,"학부":school,"학과_전공":major,"자격증":name,"우선순위":pri,"구분":kind,"주관기관":org,"추천_이유":why,"공식_사이트":link,"검토상태":"초안(검토 필요)"})
cols=list(rows[0].keys())
def write(path, rows, cols):
    with open(path,"w",encoding="utf-8-sig",newline="") as f:
        w=csv.DictWriter(f,fieldnames=cols); w.writeheader(); w.writerows(rows)
write("web/data/학과별_자격증.csv", rows, cols)
